[CmdletBinding()]
param([int]$DurationMinutes=120,[int]$IntervalSeconds=5)
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$stamp=Get-Date -Format 'yyyyMMdd-HHmmss';$dir=Join-Path $root "data\lan-smoke\$stamp";New-Item -ItemType Directory -Path $dir -Force|Out-Null;$samples=Join-Path $dir 'samples.jsonl';$summaryPath=Join-Path $dir 'summary.json';$deadline=(Get-Date).AddMinutes($DurationMinutes);$rows=@();$previousIps=@();$lastPid=$null;$lastListener=$false;$lanFail=0;$localFail=0;$maxLanFail=0;$maxLocalFail=0;$listenerDown=0;$ipChanges=0;$restartCount=0;$initialPid=$null
function Probe([string]$Url){$wire=curl.exe --connect-timeout 2 --max-time 4 -s -o NUL -w '%{http_code}|%{time_total}' $Url 2>$null;$code=0;$ms=$null;if($wire -match '^([0-9]+)\|([0-9.]+)$'){$code=[int]$Matches[1];$ms=[math]::Round([double]$Matches[2]*1000,2)};[pscustomobject]@{status=if($code -eq 200){'UP'}elseif($code -eq 503){'STARTING'}else{'DOWN'};responsive=$code -in 200,503;ready=$code -eq 200;httpCode=$code;latencyMs=$ms}}
function LanIps(){@(Get-NetIPAddress -AddressFamily IPv4 -Type Unicast|Where-Object {$_.IPAddress -notlike '127.*' -and $_.IPAddress -notlike '169.254.*' -and $_.AddressState -eq 'Preferred'}|Select-Object -ExpandProperty IPAddress)}
while((Get-Date)-lt $deadline){$ips=LanIps;$lanIp=($ips|Where-Object {$_ -like '192.168.*'}|Select-Object -First 1);if(!$lanIp){$lanIp=$ips|Select-Object -First 1};if($previousIps.Count -and (@($ips|Where-Object {$_ -notin $previousIps}).Count -or @($previousIps|Where-Object {$_ -notin $ips}).Count)){$ipChanges++};$previousIps=@($ips);$listener=Get-NetTCPConnection -LocalPort 8080 -State Listen|Select-Object -First 1;$owner=$null;if($listener){$owner=Get-CimInstance Win32_Process -Filter "ProcessId=$($listener.OwningProcess)"};$enginePid=if($listener){$listener.OwningProcess}else{$null};if($null-ne$initialPid){if($enginePid-and$enginePid-ne$lastPid){$restartCount++}}else{$initialPid=$enginePid};$lastPid=$enginePid;if(!$listener){$listenerDown++};$local=Probe 'http://127.0.0.1:8080/health';$lan=if($lanIp){Probe "http://${lanIp}:8080/health"}else{[pscustomobject]@{status='NO_LAN_IP';responsive=$false;ready=$false;httpCode=0;latencyMs=$null}};if($local.ready){$localFail=0}else{$localFail++};if($lan.ready){$lanFail=0}else{$lanFail++};$maxLocalFail=[math]::Max($maxLocalFail,$localFail);$maxLanFail=[math]::Max($maxLanFail,$lanFail);$profile=Get-NetConnectionProfile|Where-Object {$_.IPv4Connectivity -ne 'NoTraffic'}|Select-Object -First 1;$row=[ordered]@{timestamp=[DateTimeOffset]::UtcNow.ToString('o');pid=$enginePid;uptimeSeconds=if($owner){[int]((Get-Date)-$owner.CreationDate).TotalSeconds}else{$null};listener=[bool]$listener;listenerAddress=$listener.LocalAddress;local=$local;lan=$lan;lanIp=$lanIp;lanIps=$ips;networkProfile=$profile.NetworkCategory;networkInterface=$profile.InterfaceAlias;restartCount=$restartCount;lastRestartReason=$null};$row|ConvertTo-Json -Depth 10 -Compress|Add-Content -LiteralPath $samples -Encoding utf8;$rows+=[pscustomobject]$row;Start-Sleep -Seconds ([math]::Max(5,$IntervalSeconds))}
function Percentile($values,[double]$p){$v=@($values|Where-Object {$_ -ne $null}|Sort-Object);if(!$v.Count){return $null};return [math]::Round([double]$v[[math]::Min($v.Count-1,[math]::Floor(($v.Count-1)*$p))],2)}
$localReady=@($rows|Where-Object {$_.local.ready});$lanReady=@($rows|Where-Object {$_.lan.ready});$localLat=@($rows|ForEach-Object {$_.local.latencyMs});$lanLat=@($rows|ForEach-Object {$_.lan.latencyMs});$summary=[ordered]@{startedAt=$stamp;completedAt=(Get-Date).ToString('o');durationMinutes=$DurationMinutes;intervalSeconds=$IntervalSeconds;probeCount=$rows.Count;loopbackSuccessRate=if($rows.Count){$localReady.Count/$rows.Count}else{0};lanSuccessRate=if($rows.Count){$lanReady.Count/$rows.Count}else{0};maxConsecutiveLoopbackFailures=$maxLocalFail;maxConsecutiveLanFailures=$maxLanFail;p50LoopbackLatencyMs=Percentile $localLat .5;p95LoopbackLatencyMs=Percentile $localLat .95;p50LanLatencyMs=Percentile $lanLat .5;p95LanLatencyMs=Percentile $lanLat .95;restartCount=$restartCount;listenerDownCount=$listenerDown;ipChangeCount=$ipChanges;initialPid=$initialPid;finalPid=$lastPid;finalLanIps=$previousIps;pass=($rows.Count -gt 0 -and $localReady.Count/$rows.Count -ge .999 -and $lanReady.Count/$rows.Count -ge .995 -and $restartCount -eq 0 -and $listenerDown -eq 0)};$summary|ConvertTo-Json -Depth 10|Set-Content -LiteralPath $summaryPath -Encoding utf8;$summary|ConvertTo-Json -Depth 10;Write-Output "EVIDENCE_DIR=$dir";if(!$summary.pass){exit 1}
